// Validate and prepare search parameters
// Ensures we have a proper query and sets defaults

const validateSearchRequest = () => {
  const body = $('Web Search Webhook').first().json.body || {};
  const query = body.query || body.q || '';

  if (!query || typeof query !== 'string' || query.trim().length === 0) {
    return {
      error: 'Missing or invalid search query',
      code: 'INVALID_QUERY',
      success: false
    };
  }

  // Clean and prepare the query
  const cleanQuery = query.trim();

  // Extract optional parameters
  const params = {
    query: cleanQuery,
    count: Math.min(parseInt(body.count) || 5, 10), // Max 10 results
    country: body.country || 'US',
    language: body.language || 'en',
    safesearch: body.safesearch || 'moderate',
    freshness: body.freshness || null, // pd, pw, pm, py
    category: body.category || null // web, images, videos, news
  };

  return {
    success: true,
    ...params,
    timestamp: new Date().toISOString()
  };
};

return validateSearchRequest();

// Format search results for the agent
// Cleans and structures the response from Brave Search API

const formatResults = () => {
  try {
    const searchResponse = $('Brave Search API').first().json;
    const originalQuery = $('Validate Request').first().json.query;

    // Handle API errors
    if (!searchResponse || searchResponse.error) {
      return {
        success: false,
        error: searchResponse?.error?.message || 'Search API error',
        query: originalQuery,
        results: []
      };
    }

    // Extract web results
    const webResults = searchResponse.web?.results || [];

    if (webResults.length === 0) {
      return {
        success: true,
        query: originalQuery,
        message: `No results found for "${originalQuery}"`,
        results: []
      };
    }

    // Format results for agent consumption
    const formattedResults = webResults.map((result, index) => {
      return {
        rank: index + 1,
        title: result.title || 'No title',
        url: result.url,
        description: result.description || '',
        // Clean snippet by removing extra whitespace and HTML
        snippet: (result.description || '')
          .replace(/<[^>]*>/g, '') // Remove HTML tags
          .replace(/\s+/g, ' ')    // Normalize whitespace
          .trim()
          .substring(0, 200) + (result.description?.length > 200 ? '...' : ''),
        published: result.published || null,
        domain: result.url ? new URL(result.url).hostname : null
      };
    });

    // Add search metadata
    const response = {
      success: true,
      query: originalQuery,
      total_results: webResults.length,
      search_time: new Date().toISOString(),
      results: formattedResults
    };

    // Add query suggestions if available
    if (searchResponse.query?.altered) {
      response.corrected_query = searchResponse.query.altered;
    }

    return response;

  } catch (error) {
    return {
      success: false,
      error: `Result formatting error: ${error.message}`,
      query: $('Validate Request').first().json.query || 'unknown',
      results: []
    };
  }
};

return formatResults();

